parameters.jsCode:
// ============ G1 — NORMALIZAR + DESCARTES SILENCIOSOS ============
const b = $json.body || $json;
const d = b.data || {};
const key = d.key || {};
// Eco do nosso envio → descarta
if (key.fromMe === true) return [];
// Resolver o JID real: em modo LID o número verdadeiro vem em remoteJidAlt
const jidRaw = key.remoteJid || '';
const jidAlt = key.remoteJidAlt || '';
let jid = '';
if (jidRaw.endsWith('@s.whatsapp.net')) jid = jidRaw;
else if (jidRaw.endsWith('@lid') && jidAlt.endsWith('@s.whatsapp.net')) jid = jidAlt;
else return []; // grupos (@g.us), broadcast, status, LID sem alt → descarta
// Tipo de mídia e texto
const msg = d.message || {};
const tipoRaw = d.messageType || '';
let midia_tipo = 'texto';
if (tipoRaw === 'audioMessage') midia_tipo = 'audio';
else if (tipoRaw === 'imageMessage') midia_tipo = 'imagem';
else if (['videoMessage','documentMessage','stickerMessage'].includes(tipoRaw)) midia_tipo = 'outro';
let texto = msg.conversation || msg.extendedTextMessage?.text || msg.imageMessage?.caption || '';
texto = (texto || '').trim().slice(0, 2000);
if (!texto && midia_tipo === 'texto') return [];
// ===== Detectar origem de anúncio (CTWA) =====
// contextInfo pode vir em d.contextInfo ou dentro da mensagem (varia por tipo)
const ctx = d.contextInfo || msg.extendedTextMessage?.contextInfo || {};
const adReply = ctx.externalAdReply || null;
let ehAnuncio =
  ctx.entryPointConversionSource === 'ctwa_ad' ||
  ctx.conversionSource === 'FB_Ads' ||
  (adReply && adReply.sourceType === 'ad');
// patch: decodificar ctwa_clid quando vier como array de bytes (posts impulsionados FB)
const bytesParaTexto = (obj) => {
  if (!obj) return null;
  if (typeof obj === 'string') return obj;
  try {
    const vals = Object.values(obj);
    if (!vals.length || typeof vals[0] !== 'number') return null;
    return vals.map(c => String.fromCharCode(c)).join('');
  } catch (e) { return null; }
};
const ctwaClid = adReply?.ctwaClid || bytesParaTexto(ctx.ctwaPayload) || bytesParaTexto(ctx.conversionData) || null;
let anuncio = ehAnuncio ? {
  ad_source_id: adReply?.sourceId || null,
  ad_title: adReply?.title || null,
  ad_body: adReply?.body || null,
  ad_source_url: adReply?.sourceUrl || null,
  ad_app: ctx.entryPointConversionApp || adReply?.sourceApp || null,
  ctwa_clid: ctwaClid
} : null;
let origem_lead = ehAnuncio ? 'anuncio' : null;
// Normalizador de texto (compartilhado pelos fallbacks de frase)
const norm = s => (s || '').toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/\s+/g, ' ').trim();
// patch: fallback — anúncio SEM sourceId no webhook (post impulsionado no Facebook)
// identifica a campanha pela mensagem de boas-vindas personalizada no Meta
// MANUTENÇÃO: mudou a mensagem do anúncio no Meta → atualizar aqui NO MESMO DIA
if (ehAnuncio && anuncio && !anuncio.ad_source_id && texto) {
  const t = norm(texto);
  const frasesAnuncio = [
    { frase: 'quero meu raio-x gratuito', id: 'fb_post_raiox' },
    { frase: 'quero o e-book de google',  id: 'fb_post_ebook' }
  ];
  const hitAd = frasesAnuncio.find(f => t.includes(f.frase));
  if (hitAd) anuncio.ad_source_id = hitAd.id;
}
// ===== Fallback — CTA do site (mensagem pré-preenchida do wa.me) =====
// só avalia se NÃO há metadado de CTWA; o metadado sempre tem precedência
if (!ehAnuncio && texto) {
  const t = norm(texto);
  // MANUTENÇÃO: mudou o ?text= de algum botão do site → atualizar aqui NO MESMO DIA
  const ctasSite = [
    { frase: 'quero um site profissional para o meu negocio', id: 'site_cta_principal' },
    { frase: 'avaliacao da minha presenca digital',           id: 'site_cta_avaliacao' },
    { frase: 'vi o modelo de',                                id: 'site_cta_modelo' }
  ];
  const hit = ctasSite.find(c => t.includes(c.frase));
  if (hit) {
    ehAnuncio = true;          // reaproveita todo o branch de anúncio existente
    origem_lead = 'site';
    anuncio = {
      ad_source_id: hit.id,    // Buscar Anúncio encontra a linha do patch-09
      ad_title: null,
      ad_body: null,
      ad_source_url: 'https://somosatitude.com.br',
      ad_app: 'site',
      ctwa_clid: null
    };
  }
}
// Número + variantes com/sem 9º dígito
const numero = jid.split('@')[0].replace(/\D/g, '');
const variantes = new Set([numero]);
if (numero.startsWith('55')) {
  const resto = numero.slice(2);
  if (resto.length === 10) variantes.add('55' + resto.slice(0, 2) + '9' + resto.slice(2));
  if (resto.length === 11 && resto[2] === '9') variantes.add('55' + resto.slice(0, 2) + resto.slice(3));
}
return [{ json: {
  evolution_id: key.id || '',
  numero,
  variantes: [...variantes].join(','),
  texto,
  midia_tipo,
  push_name: d.pushName || '',
  ts: d.messageTimestamp || Math.floor(Date.now() / 1000),
  origem_anuncio: ehAnuncio,
  origem_lead,               // 'anuncio' | 'site' | null
  anuncio
} }];

// ============ G2 — DEDUP: se já existe, encerra ============
const resultado = $json;
const temDup = Array.isArray(resultado) ? resultado.length > 0 : Boolean(resultado.id);
if (temDup) return [];
return [{ json: $('G1 Normalizar').first().json }];

// ============ CONSOLIDAR: lead (G3) + mensagem (G1/G2) num objeto só ============
const lead = $json;
const m = $('G2 Gate Dedup').first().json;
return [{ json: {
  empresa_id: lead.id,
  slug: lead.slug,
  nome_exibicao: lead.nome_exibicao || '',
  status: lead.status || '',
  opt_out: lead.opt_out === true,
  atendimento_humano: lead.atendimento_humano === true,
  bot_suspeito: lead.bot_suspeito === true,
  estagio_conversa: lead.estagio_conversa || null,
  linha: lead.linha || null,
  numero: m.numero,
  texto: m.texto,
  midia_tipo: m.midia_tipo,
  evolution_id: m.evolution_id,
  push_name: m.push_name
} }];

// ============ G4–G6: AVALIAR ROTA (determinístico) ============
let c;
try { c = $('Consolidar Lead+Msg').first().json; } catch (e) { c = null; }
if (!c || !c.empresa_id) c = $('Consolidar Lead Anúncio').first().json;
const norm = (c.texto || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[.,!?…\s]+$/g, '').replace(/^[.,!?…\s]+/g, '').trim();

// G5 — opt-out por regra fixa (palavra/frase isolada)
const optoutRegex = /^(sair|pare|parar|remover|remove|nao quero)$/;
const ehOptout = optoutRegex.test(norm);

// G6 — sinais FORTES de robô/autoresposta
const t = norm;
const sinaisFortes = [
  'mensagem automatica', 'nao responda este', 'nao responda esta', 'atendimento eletronico',
  'digite o numero', 'digite a opcao', 'fora do horario de atendimento', 'horario de atendimento:'
];
let ehBot = sinaisFortes.some(s => t.includes(s));
// menu numerado: 2+ linhas comecando com digito + separador
const linhasMenu = (c.texto || '').split('\n').filter(l => /^\s*\d+\s*[-\.\)]/.test(l));
if (linhasMenu.length >= 2) ehBot = true;

// Decidir rota (ordem de prioridade)
let rota = 'seguir';
if (c.opt_out) rota = 'silencio';
else if (c.atendimento_humano) rota = 'humano';
else if (ehOptout) rota = 'optout';
else if (ehBot && c.bot_suspeito) rota = 'bot_trava';
else if (ehBot) rota = 'bot_marca';

// Flag: envio da msg1 nao confirmado (status ainda em fila/mensagem_gerada)
const envio_nao_confirmado = ['fila', 'mensagem_gerada'].includes(c.status);

return [{ json: { ...c, rota, envio_nao_confirmado } }];

// ============ MONTAR DOSSIÊ (Blocos A+B+C+D+E) ============
const e = $('Dossiê A: Buscar Empresa').first().json;
const historico = $('Dossiê B: Buscar Histórico').all().map(item => item.json);
const ctx = $('G4-G6 Avaliar').first().json;

// Bloco E — Origem anúncio (false para prospecção)
let an = null;
try {
  const anArr = $('Dossiê A2: Buscar Anúncio').all().map(i => i.json);
  an = anArr.length > 0 && anArr[0] && anArr[0].id ? anArr[0] : null;
} catch (err) { an = null; }
const blocoE = ['anuncio', 'site'].includes(e.origem) ? {
  veio_de_anuncio: true,
  origem: e.origem,   // 'anuncio' | 'site' — disponível pro prompt diferenciar depois
  nome_anuncio: an?.nome_interno || null,
  servico_alvo: an?.servico_alvo || null,
  promessa: an?.promessa_do_criativo || null,
  oferta: an?.oferta || null
} : { veio_de_anuncio: false };

// Bloco A — Quem é
const idadeNegocio = e.data_abertura
  ? Math.floor((Date.now() - new Date(e.data_abertura).getTime()) / (1000*60*60*24*365))
  : null;

const reviewDestaque = Array.isArray(e.gbp_reviews) && e.gbp_reviews.length > 0
  ? (e.gbp_reviews.find(r => r.text && r.text.length > 20) || e.gbp_reviews[0])
  : null;

const blocoA = {
  nome_exibicao: e.nome_exibicao || '',
  nome_socio: e.nome_socio || '',
  segmento: e.segmento || '',
  local: [e.bairro, e.municipio].filter(Boolean).join(', '),
  perfil_oferta: e.perfil_oferta || '',
  dor_resumida: e.dor_resumida || '',
  score: e.score,
  gbp: e.gbp_rating ? { rating: e.gbp_rating, avaliacoes: e.gbp_avaliacoes, review_destaque: reviewDestaque?.text?.slice(0,200) || null } : null,
  site: e.site_url ? { url: e.site_url, diagnostico: e.site_diagnostico } : null,
  instagram: e.tem_instagram ? e.instagram : null,
  idade_negocio_anos: idadeNegocio,
  rede: e.flag_rede === true,
  raiox: e.raiox_achados || null,
  // Raio-X FINANCEIRO (prefixo raiox_fin_ — LEI de isolamento; raiox_achados acima
  // e do Raio-X de PRESENCA DIGITAL, outra linha de produto).
  raiox_fin: (e.raiox_fin_nota !== null && e.raiox_fin_nota !== undefined)
    ? { nota: Number(e.raiox_fin_nota), faixa: e.raiox_fin_faixa || null, em: e.raiox_fin_em || null }
    : null
};

// Bloco B — Histórico (cronológico, mais antigo primeiro) + msg1
const historicoOrdenado = [...historico].reverse();
const msg1 = historicoOrdenado.find(h => h.etapa === 'msg1' && h.direcao === 'saida') || null;
const historicoFormatado = historicoOrdenado.map(h => ({
  quem: h.direcao === 'entrada' ? 'cliente' : 'atitude',
  etapa: h.etapa,
  texto: h.mensagem,
  intencao: h.intencao || null,
  quando: h.criado_em
}));

// Bloco C — Estado comercial
const blocoC = {
  estagio_conversa: e.estagio_conversa || 'novo',
  interesse_servicos: e.interesse_servicos || [],
  cupom_oferecido_em: e.cupom_oferecido_em || null,
  cupom_expira_em: e.cupom_expira_em || null,
  cupom_ja_expirou: e.cupom_expira_em ? new Date(e.cupom_expira_em) < new Date() : false,
  bot_suspeito: ctx.bot_suspeito === true,
  status_geral: e.status
};

// Bloco D — Agora
const blocoD = {
  mensagem_atual: ctx.texto,
  midia_tipo: ctx.midia_tipo,
  fora_janela: ctx.fora_janela === true,
  envio_nao_confirmado: ctx.envio_nao_confirmado === true,
  hora_local: new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' })
};

return [{ json: {
  empresa_id: e.id,
  slug: e.slug,
  numero: ctx.numero,
  linha: e.linha || null,
  esteira: e.esteira || null,
  bloco_a: blocoA,
  bloco_b: { msg1: msg1 ? { texto: msg1.mensagem, roteiro: msg1.roteiro_codigo } : null, historico: historicoFormatado },
  bloco_c: blocoC,
  bloco_d: blocoD,
  bloco_e: blocoE
} }];

// ============ VALIDAR CLASSIFICAÇÃO ============
// Qualquer falha de parse => neutro + confiança 0 (nunca assume categoria por engano)
const categoriasValidas = [
  'interesse_claro','pergunta_produto','pergunta_preco',
  'objecao_preco','objecao_tempo','objecao_ja_tenho','objecao_vou_pensar','objecao_desconfianca','objecao_nao_decide',
  'aceite','recusa_educada','opt_out_implicito','pedido_humano','reclamacao',
  'fora_de_contexto','confirmacao_pagamento','duvida_pos_venda','neutro'
];

let intencao = 'neutro';
let confianca = 0;
let resumo = '';

try {
  const raw = $json.content?.[0]?.text || '';
  const clean = raw.replace(/```json|```/g, '').trim();
  const p = JSON.parse(clean);
  if (categoriasValidas.includes(p.intencao)) {
    intencao = p.intencao;
    confianca = Number.isFinite(p.confianca) ? Math.max(0, Math.min(100, p.confianca)) : 50;
  }
  resumo = String(p.resumo || '').slice(0, 200);
} catch (e) {
  resumo = 'falha ao parsear classificação do Haiku — tratado como neutro/confiança 0';
}

const dossie = $('Montar Prompt Classificador').first().json;
return [{ json: { ...dossie, intencao, confianca_classificacao: confianca, resumo_classificacao: resumo } }];

// ============ MONTAR PROMPT DO GERADOR (Sonnet) ============
const d = $('Validar Classificação').first().json;
const objecoes = $('Buscar Objeções').all().map(item => item.json);
const servicos = $('Buscar Serviços').all().map(item => item.json);

// ===== Linha de produto do lead (migração 014) =====
// Gate: SÓ o lead explicitamente `financeiro` sai das regras de presença digital.
// Lead com `linha` nula mantém o comportamento anterior ao patch — escolha não-regressiva,
// pela mesma razão da emenda do W1 sobre esteira nula em inbound.
// ATENÇÃO (D33): o filtro de catálogo usa o default OPOSTO (nulo => só `ambas`).
// Unificar os dois quando a copy financeira entrar — item do checklist de disparo_financeiro.
const linhaLead = d.linha || null;
const ehFinanceiro = linhaLead === 'financeiro';

const objecoesTexto = (Array.isArray(objecoes) ? objecoes : []).map(o =>
  `### ${o.subtipo}\nContexto: ${o.contexto}\nComo responder: ${o.abordagem}\nExemplo de tom (NÃO copiar literalmente, adaptar ao lead real): ${o.exemplo}`
).join('\n\n');

const servicosTexto = (Array.isArray(servicos) ? servicos : []).map(s => {
  const cupom = s.preco_promocional
    ? ` | Preço promocional: R$ ${s.preco_promocional} com cupom ${s.cupom_codigo} (válido ${s.cupom_prazo_dias} dias a partir da 1ª menção — data exata vem calculada no dossiê, NUNCA calcular)`
    : '';
  return `### ${s.codigo} — ${s.nome}\n${s.descricao_curta}\nPreço: ${s.preco_texto}${cupom}\nPrazo: ${s.prazo_entrega || 'não aplicável'}\nLink de checkout: ${s.link_checkout}\nQuando ofertar: ${s.quando_ofertar}`;
}).join('\n\n');

// Cupom: já foi oferecido? já expirou?
const cupomInfo = d.bloco_c.cupom_oferecido_em
  ? (d.bloco_c.cupom_ja_expirou
      ? `Cupom PRIME30 JÁ FOI OFERECIDO e EXPIROU em ${d.bloco_c.cupom_expira_em}. NÃO reoferecer nem prorrogar de cabeça — se o cliente perguntar do prazo, escale para humano (ação escalar_humano:oferta_expirada).`
      : `Cupom PRIME30 já foi oferecido em ${d.bloco_c.cupom_oferecido_em}, válido até ${d.bloco_c.cupom_expira_em}. Pode reforçar a validade se o cliente perguntar, mas não é preciso reapresentar a oferta do zero.`)
  : 'Cupom PRIME30 AINDA NÃO foi oferecido a este lead. Se for apresentar o preço de criacao_site/redesign_site pela primeira vez nesta conversa, você pode mencionar o cupom UMA VEZ — a ação "registrar_oferta_cupom" deve constar em "acoes" nesse caso para o sistema calcular e gravar a data de validade.';

// ===== Modo anúncio / origem site: regras específicas por origem =====
const origemLead = d.bloco_e?.origem || (d.bloco_e?.veio_de_anuncio ? 'anuncio' : null);
let modoAnuncio = '';

if (!ehFinanceiro && d.bloco_e?.veio_de_anuncio && origemLead === 'site') {
  modoAnuncio = `

ORIGEM SITE — este lead navegou no somosatitude.com.br e clicou num botão de WhatsApp. Regras específicas que PREVALECEM sobre o fluxo consultivo padrão:
- CTA clicado: "${d.bloco_e.nome_anuncio || 'não identificado'}". Contexto do que ele viu: "${d.bloco_e.promessa || 'não cadastrado'}".
- Ele JÁ VIU o site institucional: preço cheio (R$ 599), prazo (até 10 dias úteis após o formulário), hospedagem R$ 79/mês só após a entrega, garantia de 7 dias. Pode referenciar essas informações com naturalidade — são públicas para ele.
- NENHUM cupom é anunciado nem oferecido proativamente. O preço é R$ 599. O cupom PRIME30 (R$ 419,30) SÓ pode aparecer como facilitador em objeção de preço explícita (intenção objecao_preco), seguindo a base de objeções — nunca antes, nunca como boas-vindas, nunca se o lead já aceitou o preço cheio. Ao mencionar pela primeira vez, incluir a ação "registrar_oferta_cupom". O cupom SITE30 é EXCLUSIVO de anúncio pago — NUNCA usar para lead do site.
- Você NÃO tem dados enriquecidos deste lead (não houve análise do negócio dele). NUNCA afirme que analisou algo dele.
- Se o CTA for "Site — CTA principal": lead decidido — não pergunte se ele quer um site; vá direto à pergunta de contexto (qual é o negócio dele e se já tem site hoje ou seria o primeiro), e siga: contexto → conectar o site ao negócio em 1-2 linhas → confirmar preço/prazo com pergunta de encaminhamento → mediante aceite, enviar_checkout:criacao_site (mencionando a hospedagem de forma natural, nunca como taxa).
- Se o CTA for "Site — CTA avaliação": a promessa é uma AVALIAÇÃO, não uma venda. Primeiro entregue o prometido: colete nome do negócio, cidade e site ou Instagram (1 pergunta por vez, começando por negócio+cidade juntos). Com os dados coletados, use escalar_humano:avaliacao_site e avise o lead que a avaliação chega em até 1 dia útil. NÃO oferte preço antes de a avaliação ser entregue, a menos que o lead pergunte.
- Se o CTA for "Site — veio de um modelo": a mensagem dele diz qual modelo/segmento viu — use isso como abertura e siga a mesma jornada do CTA principal, já com o segmento conhecido. Lembre: os modelos são demonstrações fictícias; o site dele é feito do zero com a marca dele.
- Se o lead JÁ TEM site: mesma jornada e mesmo link — apenas mude a comunicação para refazer/modernizar (redesign_site). Não mude de produto.
- ATALHO: se o lead pedir o link ou o preço diretamente, não segure — responda e, havendo aceite, envie o checkout no mesmo turno.
- Checkout de produto DIFERENTE de criacao_site/redesign_site só se o próprio lead pedir explicitamente.`;
} else if (!ehFinanceiro && d.bloco_e?.veio_de_anuncio) {
  modoAnuncio = `

MODO ANÚNCIO — este lead veio de um anúncio pago. Regras específicas que PREVALECEM sobre o fluxo consultivo padrão:
- O lead clicou no anúncio "${d.bloco_e.nome_anuncio || 'não cadastrado'}". Promessa que ele viu: "${d.bloco_e.promessa || 'não cadastrada'}". Oferta do criativo: "${d.bloco_e.oferta || 'não cadastrada'}".
- Sua primeira missão é responder ao que o anúncio prometeu — nunca mude de assunto na abertura.
- Preço do criativo é público: se o anúncio anunciou preço/oferta, o lead já viu — responda perguntas de preço imediatamente, sem rodeio, usando exatamente o valor da oferta acima.
- O cupom PRIME30 NÃO se aplica a leads de anúncio — NUNCA mencioná-lo. Se o anúncio tiver cupom próprio, ele está descrito na oferta acima — use SÓ esse. Cupom de campanha não tem contagem por lead: NUNCA invente data de validade; se perguntarem até quando vale, diga que é o cupom da campanha atual. Dúvida de prazo além disso → escalar_humano. EXCEÇÃO: ver seção MODO AVALIAÇÃO abaixo, quando presente — ela pode liberar o PRIME30 especificamente para o ramo de avaliação de presença.
- Você NÃO tem dados enriquecidos deste lead (não houve análise do negócio dele). NUNCA afirme que analisou algo dele. Colete com naturalidade, 1 pergunta por vez, só o que ajudar a atender.
- Upsell só depois de resolver (ou o lead recusar) o que ele veio buscar.
- ESTRATÉGIA PELO PRODUTO-ALVO (${d.bloco_e.servico_alvo || 'não identificado'}):
  * ebook_gbp / ebook_gestao — VENDA DIRETA: sem qualificação. Confirme o que o e-book entrega (1-2 linhas alinhadas à promessa) + pergunte se pode mandar o link. Ao primeiro sim (ou pedido direto), enviar_checkout do e-book + registrar_interesse. Entrega imediata por e-mail após confirmação do pagamento (é automático). Se o lead não for do segmento do criativo, adapte naturalmente — o conteúdo serve para qualquer negócio local; nunca diga que o anúncio "não era para ele".
  * criacao_site — MINI-QUALIFICAÇÃO (2 trocas antes do checkout): Troca 1 = boas-vindas + UMA pergunta dupla (qual é o negócio + já tem site hoje ou seria o primeiro). Troca 2 = conectar o site ao negócio informado em 1-2 linhas + confirmar o caminho (pronto em até 10 dias úteis após formulário rápido, preço da oferta do criativo, parcela no cartão) + pergunta de encaminhamento. Troca 3 = mediante aceite, enviar_checkout:criacao_site lembrando o cupom do criativo + mencionar de forma natural (nunca como taxa) a hospedagem R$ 79/mês após a entrega. Se JÁ TEM site: mesma jornada e link, comunicação de refazer/modernizar (redesign_site). ATALHO: lead pede link/preço direto na 1ª mensagem → responda e envie o checkout no mesmo turno. Objeção de preço: facilitador é o cupom do criativo + parcelamento + hospedagem só após entrega; pedido de desconto extra → escalar_humano.
