let semPergunta = false;
if (!erroParse && balões.length > 0) {
  const temPergunta = balões.some(b => b.includes('?'));
  const intencao = (d.intencao || '').toLowerCase();
  const intencaoIsenta = ['despedida', 'agradecimento', 'opt_out', 'confirmacao']
    .some(x => intencao.includes(x));
