// ============ VALIDAR RESPOSTA DO GERADOR ============
const d = $('Montar Prompt Gerador').first().json;

let resposta = null;
let acoes = [];
let confianca = 0;
let erroParse = false;

try {
  const raw = $json.content?.[0]?.text || '';
  const clean = raw.replace(/```json|```/g, '').trim();
  const p = JSON.parse(clean);
  resposta = p.resposta || null;
  acoes = Array.isArray(p.acoes) ? p.acoes : [];
  confianca = Number.isFinite(p.confianca) ? Math.max(0, Math.min(100, p.confianca)) : 0;
} catch (e) {
  erroParse = true;
}

// Normaliza resposta para array de balões (1 ou 2 mensagens curtas)
let balões = [];
if (Array.isArray(resposta)) balões = resposta.filter(Boolean);
else if (typeof resposta === 'string' && resposta.trim()) balões = [resposta.trim()];

// Falha de parse ou resposta vazia => força confiança 0 (nunca envia sem revisão)
if (erroParse || balões.length === 0) {
  confianca = 0;
  acoes = ['escalar_humano:falha_geracao'];
}

// ===== CHECK DETERMINÍSTICO: fechamento com pergunta/CTA (princípio 11) =====
// Se nenhum balão contém "?", e não é caso de exceção, rebaixa a confiança
// para <70 => Gate Autonomia retém para revisão humana em vez de enviar.
let semPergunta = false;
if (!erroParse && balões.length > 0) {
  const temPergunta = balões.some(b => b.includes('?'));
  const intencao = (d.intencao || '').toLowerCase();
  const intencaoIsenta = ['despedida', 'agradecimento', 'opt_out', 'confirmacao']
    .some(x => intencao.includes(x));
  const acaoIsenta = acoes.some(a =>
    String(a).startsWith('enviar_checkout') ||
    String(a).startsWith('escalar_humano') ||
    String(a).startsWith('enviar_link_raiox')
  );
  if (!temPergunta && !intencaoIsenta && !acaoIsenta) {
    semPergunta = true;
    confianca = Math.min(confianca, 65);
  }
}

return [{ json: {
  ...d,
  resposta_balões: balões,
  acoes_sugeridas: acoes,
  confianca_geracao: confianca,
  erro_parse_gerador: erroParse,
  flag_sem_pergunta: semPergunta
} }];

// ============ CONSOLIDAR LEAD DE ANÚNCIO (formato do Consolidar Lead+Msg) ============
// O POST com return=representation devolve um array com o registro criado/atualizado
const resp = $json;
const lead = Array.isArray(resp) ? resp[0] : resp;
const m = $('G2 Gate Dedup').first().json;
const anuncioCatalogo = $('Buscar Anúncio').all().map(i => i.json);
const an = Array.isArray(anuncioCatalogo) && anuncioCatalogo.length > 0
  ? (Array.isArray(anuncioCatalogo[0]) ? anuncioCatalogo[0][0] : anuncioCatalogo[0])
  : null;

if (!lead || !lead.id) {
  // Upsert falhou ou não retornou representação — não seguir sem empresa_id
  throw new Error('Criar Lead Anúncio não retornou id. Verifique unique index em empresas.whatsapp e o header Prefer.');
}

return [{ json: {
  empresa_id: lead.id,
  slug: lead.slug,
  nome_exibicao: lead.nome_exibicao || '',
  status: lead.status || 'respondeu',
  opt_out: lead.opt_out === true,
  atendimento_humano: lead.atendimento_humano === true,
  bot_suspeito: lead.bot_suspeito === true,
  estagio_conversa: lead.estagio_conversa || 'em_conversa',
  numero: m.numero,
  texto: m.texto,
  midia_tipo: m.midia_tipo,
  evolution_id: m.evolution_id,
  push_name: m.push_name,
  origem: 'anuncio',
  linha: lead.linha || null,
  anuncio_id: lead.anuncio_id || null,
  anuncio_nome: (an && an.nome_interno) || (m.anuncio && m.anuncio.ad_body) || null,
  anuncio_servico_alvo: (an && an.servico_alvo) || null
} }];

// ============ GATE AUTONOMIA — decide envio direto vs retenção ============
const d = $json; // saída de "Validar Resposta Gerador"

const CONFIANCA_MINIMA = 70;

const acoes = Array.isArray(d.acoes_sugeridas) ? d.acoes_sugeridas : [];
const temEscalarHumano = acoes.some(a => String(a || '').trim().startsWith('escalar_humano'));
const confiancaBaixa = (d.confianca_geracao ?? 0) < CONFIANCA_MINIMA;
const semBaloes = !Array.isArray(d.resposta_balões) || d.resposta_balões.length === 0;

// D34 REVOGADA em 14/08/2026, com autorização explícita do dono.
// A premissa era "enquanto o bloco REGRAS FINANCEIRO do gerador estiver vazio".
// MEDIDO em 14/08: o bloco NÃO está mais vazio — o `Montar Prompt Gerador` traz 6
// regras da linha financeira e, no ramo `ehFinanceiro`, REMOVE do prompt todo o
// conteúdo de presença digital (princípios 7-10, portfólio, cupom PRIME30,
// MODO ANÚNCIO, MODO AVALIAÇÃO). Catálogo medido: 4 serviços e 6 objeções com
// linha='financeiro'. A trava havia sobrevivido à condição que a justificava.
//
// ⚠ O QUE ISSO CUSTA, e foi aceito conscientemente: o A2 Resposta NÃO tem
// `modo_teste` (exceção conhecida da LEI) e esta era a única contenção específica
// da linha financeira. A validação da copy passa a ser AO VIVO, pelo dono lendo o
// WhatsApp oficial. As demais retenções continuam de pé.
//
// Rollback: workflows/_backup/A2-Resposta-Gate-Autonomia-2026-08-14.json
// ou n8n_workflow_versions rollback -> versionId 495.

let motivoRetencao = null;
if (d.erro_parse_gerador) motivoRetencao = 'falha_parse_gerador';
else if (semBaloes) motivoRetencao = 'resposta_vazia';
else if (temEscalarHumano) motivoRetencao = 'acao_escalar_humano';
else if (confiancaBaixa) motivoRetencao = 'confianca_baixa';

const retido = motivoRetencao !== null;

return [{ json: { ...d, retido, motivo_retencao: motivoRetencao } }];

