// ============ E1 v2 — PARSEAR AÇÕES (fluxo direto, sem aprovação) ============
const origem = $('Gate Autonomia').first().json;

const acoes = Array.isArray(origem.acoes_sugeridas) ? origem.acoes_sugeridas : [];
const suportadas = ['agendar_followup', 'registrar_oferta_cupom', 'atualizar_estagio', 'registrar_interesse'];
const out = [];

for (const a of acoes) {
  const s = String(a || '').trim();
  if (!s || s === 'nenhuma') continue;
  const [tipo, ...resto] = s.split(':');
  const param = resto.join(':').trim() || null;
  if (suportadas.includes(tipo)) {
    out.push({ json: { empresa_id: origem.empresa_id, tipo, param } });
  }
}

return out; // vazio = nenhuma ação, fluxo encerra

