// ============ B4 — CONSOLIDAR RAJADA ============
// O PATCH do B3 retornou APENAS as linhas que ESTA execução capturou.
// Zero linhas => outra execução (a primeira da rajada) já levou tudo => encerra.
// Atenção fan-out do n8n: multi-row vira múltiplos items => usar .all()
const capturadas = $input.all()
  .map(i => i.json)
  .filter(r => r && r.id);

if (capturadas.length === 0) return [];

// Ordena por chegada e agrega os textos em uma mensagem única
capturadas.sort((a, b) => new Date(a.recebida_em) - new Date(b.recebida_em));
const textoAgregado = capturadas
  .map(r => (r.mensagem || '').trim())
  .filter(Boolean)
  .join('\n');

// Base = payload original normalizado desta execução
const base = $('G2 Gate Dedup').first().json;

return [{ json: {
  ...base,
  texto: textoAgregado || base.texto,
  rajada_qtd: capturadas.length,
  rajada_evolution_ids: capturadas.map(r => r.evolution_id).filter(Boolean)
} }];
